import unittest

from solution import merge_snapshot


class MergeSnapshotTests(unittest.TestCase):
    def test_recursive_merge_and_required_paths(self):
        defaults = {
            "service": {"host": "localhost", "port": 80, "auth": {"token": None}},
            "features": {"enabled": False},
        }
        snapshot = {"service": {"port": 443, "auth": {"token": "secret"}}}
        result = merge_snapshot(defaults, snapshot, ["service.host", "service.auth.token"])
        self.assertEqual(result, {
            "service": {"host": "localhost", "port": 443, "auth": {"token": "secret"}},
            "features": {"enabled": False},
        })

    def test_empty_values(self):
        self.assertEqual(merge_snapshot({}, {}, []), {})
        self.assertEqual(merge_snapshot({"empty": {}}, {"empty": {}}, []), {"empty": {}})

    def test_full_deep_copy_and_no_mutation(self):
        defaults = {"a": {"items": [1, {"x": [2]}]}, "b": {"keep": [3]}}
        snapshot = {"a": {"items": [4, {"y": [5]}]}}
        defaults_before = {"a": {"items": [1, {"x": [2]}]}, "b": {"keep": [3]}}
        snapshot_before = {"a": {"items": [4, {"y": [5]}]}}
        result = merge_snapshot(defaults, snapshot, [])
        self.assertEqual(defaults, defaults_before)
        self.assertEqual(snapshot, snapshot_before)
        self.assertIsNot(result["a"], defaults["a"])
        self.assertIsNot(result["a"]["items"], snapshot["a"]["items"])
        self.assertIsNot(result["a"]["items"][1], snapshot["a"]["items"][1])
        self.assertIsNot(result["a"]["items"][1]["y"], snapshot["a"]["items"][1]["y"])
        self.assertIsNot(result["b"]["keep"], defaults["b"]["keep"])
        result["a"]["items"][1]["y"].append(9)
        result["b"]["keep"].append(9)
        self.assertEqual(defaults, defaults_before)
        self.assertEqual(snapshot, snapshot_before)

    def test_declared_container_types(self):
        valid = ({}, {}, [])
        for position, bad in ((0, []), (1, []), (2, ())):
            args = list(valid)
            args[position] = bad
            with self.subTest(position=position, bad=bad):
                with self.assertRaises(TypeError):
                    merge_snapshot(*args)

    def test_dictionary_keys_at_all_depths(self):
        invalid_dicts = [
            {1: "x"},
            {"": "x"},
            {"outer": {False: "x"}},
            {"outer": {"": "x"}},
        ]
        for invalid in invalid_dicts:
            with self.subTest(defaults=invalid):
                with self.assertRaises((TypeError, ValueError)):
                    merge_snapshot(invalid, {}, [])
        for invalid in invalid_dicts:
            with self.subTest(snapshot=invalid):
                with self.assertRaises((TypeError, ValueError)):
                    merge_snapshot({"outer": {}}, invalid, [])

    def test_required_path_validation(self):
        for path in (1, None, True):
            with self.subTest(path=path):
                with self.assertRaises(TypeError):
                    merge_snapshot({}, {}, [path])
        for path in ("", ".a", "a.", "a..b"):
            with self.subTest(path=path):
                with self.assertRaises(ValueError):
                    merge_snapshot({}, {}, [path])

    def test_unknown_keys_and_structural_mismatches(self):
        with self.assertRaises(ValueError):
            merge_snapshot({"a": 1}, {"b": 2}, [])
        with self.assertRaises(ValueError):
            merge_snapshot({"a": {"b": 1}}, {"a": {"c": 2}}, [])
        with self.assertRaises(ValueError):
            merge_snapshot({"a": {}}, {"a": 1}, [])
        with self.assertRaises(ValueError):
            merge_snapshot({"a": 1}, {"a": {}}, [])

    def test_missing_or_none_required_value(self):
        with self.assertRaises(ValueError):
            merge_snapshot({"a": {}}, {}, ["a.b"])
        with self.assertRaises(ValueError):
            merge_snapshot({"a": {"b": None}}, {}, ["a.b"])
        self.assertEqual(merge_snapshot({"a": {"b": 0}}, {}, ["a.b"])["a"]["b"], 0)


if __name__ == "__main__":
    unittest.main()

